                ihevcd_fmt_conv_420sp_to_420sp_ft *fmt_conv_fptr;
                if(ps_codec->i4_disp_wd >= MIN_FMT_CONV_SIMD_WIDTH)
                {
                    fmt_conv_fptr = ps_codec->s_func_selector.ihevcd_fmt_conv_420sp_to_420sp_fptr;
